static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

