    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_1 2
#define PIN_2 3

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    signal(SIGINT, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, PIN_1);
    line2 = gpiod_chip_get_line(chip, PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line1");
            break;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line2");
            break;
        }
        printf("GPIO %d HIGH, GPIO %d LOW\n", PIN_1, PIN_2);
        usleep(100000);

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line1");
            break;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line2");
            break;
        }
        printf("GPIO %d LOW, GPIO %d HIGH\n", PIN_1, PIN_2);
        usleep(100000);
    }

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define SLEEP_SECONDS 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value low */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d set to output mode.\n", GPIO_LINE_OFFSET);

    while (running) {
        int value = 1; /* Digital HIGH */

        if (gpiod_line_set_value(line, value) < 0) {
            fprintf(stderr, "Failed to write to GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);

        sleep(SLEEP_SECONDS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word:
 *   Bit 15    OS: assert start single conversion
 *   Bits 14:12 MUX: AIN0 vs GND (0x4)
 *   Bits 11:9  PGA: +/-4.096 V (0x0)
 *   Bit  8     MODE: single-shot (0)
 *   Bits 7:5   DR: 128 SPS (0x4)
 *   Bit  4     COMP_MODE: traditional
 *   Bit  3     COMP_POL: active low
 *   Bit  2     COMP_LAT: non-latching
 *   Bits 1:0   COMP_QUE: disable comparator (0x3)
 */
#define ADS1115_CONFIG_BASE 0x8483

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int fd;
    uint8_t reg;
    uint8_t buf[2];
    int16_t raw;
    float voltage;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Point to config register and write the config word */
    reg = ADS1115_REG_CONFIG;
    if (write(fd, &reg, 1) != 1) {
        perror("write config pointer");
        close(fd);
        return EXIT_FAILURE;
    }
    uint16_t cfg = ADS1115_CONFIG_BASE;
    buf[0] = (uint8_t)(cfg >> 8);
    buf[1] = (uint8_t)(cfg & 0xFF);
    if (write(fd, buf, 2) != 2) {
        perror("write config");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        /* Trigger a new conversion by setting bit 15 of the config */
        cfg |= 0x8000;
        buf[0] = (uint8_t)(cfg >> 8);
        buf[1] = (uint8_t)(cfg & 0xFF);
        if (write(fd, buf, 2) != 2) {
            perror("trigger conversion");
            break;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        usleep(10000);

        /* Point to conversion register */
        reg = ADS1115_REG_CONVERSION;
        if (write(fd, &reg, 1) != 1) {
            perror("write conv pointer");
            break;
        }

        /* Read 2 bytes */
        if (read(fd, buf, 2) != 2) {
            perror("read conv");
            break;
        }

        raw = (int16_t)((buf[0] << 8) | buf[1]);
        voltage = (float)raw * 4.096f / 32768.0f;

        printf("AIN0: %.4f V\n", voltage);
        fflush(stdout);

        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_TA   0x06

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *out) {
    uint8_t buf[3];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) return -1;
    if (read(fd, buf + 1, 2) != 2) return -1;
    uint16_t raw = ((uint16_t)buf[2] << 8) | buf[1];
    *out = (float)((int16_t)raw) * 0.02f - 273.15f;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float temp;
        if (i2c_read_reg16(fd, MLX90614_TA, &temp) == 0) {
            printf("Ambient Temperature: %.2f °C\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

