#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (hardware not available).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int level = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, level) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM on GPIO %d set to %d/%d\n", PWM_PIN, level, PWM_RANGE);
        fflush(stdout);

        level = (level + 1) % (PWM_RANGE + 1);
        time_sleep(0.5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define CHIP_NAME "gpiochip0"
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long)(end->tv_sec - start->tv_sec) * 1000000L +
           (end->tv_nsec - start->tv_nsec) / 1000L;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        struct timespec t_start, t_end;
        long pulse_us = -1;

        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(2);

        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(10);

        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to reset trigger: %s\n", strerror(errno));
            goto cleanup;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_start);
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 1) break;
            if (elapsed_us(&t_start, &(struct timespec){.tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000}) > 0) {
                fprintf(stderr, "Timeout waiting for echo rising edge.\n");
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        clock_gettime(CLOCK_MONOTONIC, &t_start);
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 0) break;
            if (elapsed_us(&t_start, &(struct timespec){.tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000}) > 0) {
                fprintf(stderr, "Timeout waiting for echo falling edge.\n");
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        clock_gettime(CLOCK_MONOTONIC, &t_end);
        pulse_us = elapsed_us(&t_start, &t_end);

        if (pulse_us < 0 || pulse_us > 30000) {
            fprintf(stderr, "Invalid pulse width: %ld us\n", pulse_us);
            goto cleanup;
        }

        float distance = (float)pulse_us / 58.0f;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x28

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 vs GND, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000 | (0x4000) | (0x0000) | (0x0080) | (0x0003)

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading config register */
    uint16_t cfg_check = 0;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    printf("ADS1115 detected (config=0x%04X). Sampling every 5 s...\n", cfg_check);

    while (g_running) {
        uint16_t cfg = ADS1115_CFG_BASE | (1 << 15); /* assert OS bit to start conversion */
        if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) {
            fprintf(stderr, "Failed to write config: %s\n", strerror(errno));
            break;
        }

        /* Wait for conversion (~8 ms at 128 SPS, use 10 ms margin) */
        usleep(10000);

        uint16_t raw = 0;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion: %s\n", strerror(errno));
            break;
        }

        /* Validity check: bit 15 of config should reflect conversion state */
        uint16_t cfg_readback = 0;
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_readback) < 0) {
            fprintf(stderr, "Failed to read config back: %s\n", strerror(errno));
            break;
        }
        if (!(cfg_readback & 0x8000)) {
            fprintf(stderr, "Conversion not complete (cfg=0x%04X)\n", cfg_readback);
            break;
        }

        /* Convert raw to signed 16-bit and scale to volts (+/-4.096V range) */
        int16_t signed_raw = (int16_t)raw;
        double voltage = (signed_raw * 4.096) / 32768.0;

        printf("AIN0: %.4f V\n", voltage);
        fflush(stdout);

        /* Sleep 5 s in 100 ms slices so SIGINT is responsive */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

