#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   (1 << 15)
#define ADS1115_CFG_MUX_CH0    (0x04 << 12) /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V (0x01 << 9)
#define ADS1115_CFG_MODE_SS   (0x01 << 8)
#define ADS1115_CFG_DR_128SPS (0x00 << 5)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Single-shot conversion on AIN0, +/-4.096V, 128 SPS */
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_CH0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128SPS;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        perror("write config");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wait for conversion (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
        perror("read conversion");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Convert to signed 16-bit */
    int16_t value = (int16_t)raw;
    printf("AIN0: %d\n", value);

    close(fd);
    return EXIT_SUCCESS;
}

