#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int read_input(const char *prompt, char *buffer, size_t buffer_size) {
    printf("%s", prompt);
    fflush(stdout);

    if (!fgets(buffer, (int)buffer_size, stdin)) {
        if (feof(stdin)) {
            fprintf(stderr, "\nEnd of input reached.\n");
        } else {
            fprintf(stderr, "\nError reading input: %s\n", strerror(errno));
        }
        return -1;
    }

    size_t len = strlen(buffer);
    if (len > 0 && buffer[len - 1] == '\n') {
        buffer[len - 1] = '\0';
    }
    return 0;
}

static int validate_input(const char *input) {
    if (strcmp(input, "on") == 0 || strcmp(input, "off") == 0) {
        return 0;
    }
    fprintf(stderr, "Invalid input. Please enter 'on' or 'off'.\n");
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line 17");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("Failed to request GPIO line 17 as output");
        goto cleanup;
    }

    char input_buffer[32];
    while (running) {
        if (read_input("Enter 'on' or 'off': ", input_buffer, sizeof(input_buffer)) != 0) {
            break;
        }

        if (validate_input(input_buffer) != 0) {
            continue;
        }

        int value = (strcmp(input_buffer, "on") == 0) ? 1 : 0;

        if (gpiod_line_set_value(line, value) < 0) {
            perror("Failed to set GPIO value");
            break;
        }

        printf("GPIO 17 is now %s\n", input_buffer);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

