}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines %d/%d: %s\n",
                GPIO_2, GPIO_3, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-toggle", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val2 < 0 || val3 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            goto cleanup;
        }

        int next2 = val2 ^ 1;
        int next3 = val3 ^ 1;

        if (gpiod_line_set_value(line2, next2) < 0 ||
            gpiod_line_set_value(line3, next3) < 0) {
            fprintf(stderr, "Error writing GPIO values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_2, next2, GPIO_3, next3);
        fflush(stdout);

        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value low */
    if (gpiod_line_request_output(line17, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d set to LOW\n", GPIO_17, GPIO_18);
    fflush(stdout);

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0 || gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Error: failed to set HIGH: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set to HIGH\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(DELAY_MS * 1000);

        if (!running) break;

        if (gpiod_line_set_value(line17, 0) < 0 || gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Error: failed to set LOW: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set to LOW\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(DELAY_MS * 1000);
    }

