    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip)   gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define CMD_MEASURE_TEMP   0xF3
#define MAX_RETRIES        3
#define POLL_DELAY_US      10000   /* 10 ms between status polls */
#define MEAS_TIMEOUT_MS    200     /* max wait for conversion */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a single command byte to the device. Returns 0 on success, -1 on error. */
static int si7021_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read N bytes from the device. Returns 0 on success, -1 on error.
 * Uses a loop so we can retry transient short-reads.
 */
static int si7021_read_bytes(int fd, uint8_t *buf, size_t n)
{
    size_t got = 0;
    while (got < n) {
        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (device disconnected?)\n");
            return -1;
        }
        got += (size_t)r;
    }
    return 0;
}

/*
 * Trigger a temperature measurement and read the 3-byte result.
 * Returns 0 on success, -1 on error.
 */
static int si7021_read_temp(int fd, float *temp_out)
{
    uint8_t data[3];

    if (si7021_write_cmd(fd, CMD_MEASURE_TEMP) < 0)
        return -1;

    /* Poll the clock-harvesting bit until it clears (measurement ready). */
    for (int i = 0; i < MEAS_TIMEOUT_MS / 10; i++) {
        uint8_t status;
        if (si7021_read_bytes(fd, &status, 1) < 0)
            return -1;
        if ((status & 0x01) == 0)
            break;
        usleep(POLL_DELAY_US);
        if (i == MEAS_TIMEOUT_MS / 10 - 1) {
            fprintf(stderr, "Temperature measurement timeout\n");
            return -1;
        }
    }

    if (si7021_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* CRC-8 polynomial 0x31, init 0x00 (SiLabs spec). */
    uint8_t crc = 0x00;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    if (crc != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temp_out = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Probe: try a zero-length write to confirm the device ACKs.
     * A NACK here usually means the device is not present.
     */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "No ACK from SI7021 at 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7021_read_temp(fd, &temp) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(100000); /* 100 ms backoff before retry */
        }

        if (ok)
            printf("Temperature: %.2f C\n", temp);
        else
            fprintf(stderr, "Failed to read temperature after %d attempts.\n",
                    MAX_RETRIES);

        /* Sleep 5 s in 100 ms slices so SIGINT is caught promptly. */
        for (int s = 0; s < 50 && g_running; s++)
            usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 vs GND, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000 | (0x4000) | (0x0000) | (0x0080) | (0x0003)

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading config register */
    uint16_t cfg_check;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting 3-sample acquisition.\n", cfg_check);

    for (int i = 0; i < 3 && g_running; i++) {
        uint16_t cfg = ADS1115_CFG_BASE | (0x8000); /* assert OS bit to start conversion */
        if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) {
            fprintf(stderr, "Failed to write config: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        /* Wait for conversion (~8ms at 128 SPS, use 10ms margin) */
        usleep(10000);

        uint16_t raw;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        int16_t signed_val = (int16_t)raw;
        printf("Sample %d: raw=0x%04X (%d)\n", i + 1, raw, signed_val);

        if (i < 2 && g_running) sleep(1);
    }

    close(fd);
    return EXIT_SUCCESS;
}

