                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < 256 && running; cycle++) {
        int value = (cycle & 1) ? 1 : 0;
        printf("Cycle %d: setting all pins to %d\n", cycle, value);
        fflush(stdout);

        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], value) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u: %s\n",
                        pins[i], strerror(errno));
                goto cleanup;
            }
        }

        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

