#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11};

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Open the default gpiochip (gpiochip0 on most Raspberry Pi models). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get each line individually so we can release them separately. */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
    }

    /* Request each line as output, initial value low. */
    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting digital output toggle on GPIO 8, 9, 10, 11 (BCM).\n");
    fflush(stdout);

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value high");
                goto cleanup;
            }
        }
        printf("GPIO 8, 9, 10, 11 -> HIGH\n");
        fflush(stdout);

        usleep(100000);

        if (!running)
            break;

        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value low");
                goto cleanup;
            }
        }
        printf("GPIO 8, 9, 10, 11 -> LOW\n");
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually. */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nClean shutdown.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_1 2
#define PIN_2 3

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, PIN_1);
    line2 = gpiod_chip_get_line(chip, PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        printf("GPIO %d: HIGH, GPIO %d: HIGH\n", PIN_1, PIN_2);
        fflush(stdout);
        gpiod_line_set_value(line1, 1);
        gpiod_line_set_value(line2, 1);
        usleep(500000);

        if (!keep_running) break;

        printf("GPIO %d: LOW, GPIO %d: LOW\n", PIN_1, PIN_2);
        fflush(stdout);
        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 0);
        usleep(500000);
    }

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define MAX_DISTANCE_CM 400.0f
#define SOUND_SPEED_CM_PER_S 34300.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long long elapsed_us;
    int val;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout after ~50 ms) */
    for (int i = 0; i < 50000; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo pin: %s\n", strerror(errno));
            return -1.0f;
        }
        if (val == 1) break;
        usleep(1);
    }
    if (val != 1) {
        fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge (timeout after ~50 ms) */
    for (int i = 0; i < 50000; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo pin: %s\n", strerror(errno));
            return -1.0f;
        }
        if (val == 0) break;
        usleep(1);
    }
    if (val != 0) {
        fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_us = (long long)(end.tv_sec - start.tv_sec) * 1000000LL +
                 (end.tv_nsec - start.tv_nsec) / 1000LL;

    /* distance = (elapsed_us * speed_of_sound) / 2 */
    float distance = (float)elapsed_us * SOUND_SPEED_CM_PER_S / 2000000.0f;

    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm exceeds max (%.0f cm)\n",
                distance, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Error: cannot get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: cannot get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: cannot request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: cannot request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float dist = measure_distance(trig, echo);
        if (dist >= 0.0f) {
            printf("Distance: %.2f cm\n", dist);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        sleep(1);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

