        fprintf(stderr, "Error: Invalid value %d. Must be between %d and %d.\n", value, MIN_VALUE, MAX_VALUE);
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

