#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val == target) return 0;
        if (val < 0) return -1;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > timeout_us) return 1;
    }
    return 2;
}

static int read_dht11(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int laststate = 1;
    int counter = 0;
    int j = 0;

    /* Start signal: pull low for >= 1ms, then high */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, "dht11") < 0) return -1;

    /* Wait for sensor to pull low (response) */
    int rc = wait_for_level(line, 0, 1000);
    if (rc != 0) return -1;

    /* Sensor response: ~80us low, ~80us high */
    rc = wait_for_level(line, 1, 1000);
    if (rc != 0) return -1;
    rc = wait_for_level(line, 0, 1000);
    if (rc != 0) return -1;

    /* Read 40 bits */
    for (int i = 0; i < MAX_TIMINGS && running; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        laststate = gpiod_line_get_value(line);

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) return -1;

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)data[0];
    *temp = (float)data[2];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    float temp, hum;
    int ret = read_dht11(line, &temp, &hum);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (ret == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        return EXIT_SUCCESS;
    } else if (ret == 2) {
        fprintf(stderr, "Interrupted by signal.\n");
        return EXIT_FAILURE;
    } else {
        fprintf(stderr, "DHT11 read failed (device absent or bus error).\n");
        return EXIT_FAILURE;
    }
}

