#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device not found or insufficient permissions).\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM applied to GPIO %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        for (int i = 0; i < 3; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM disabled on GPIO %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        time_sleep(0.15);
    }

    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

