#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT  0x00
#define REG_CONFIG  0x01

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure: RN=1100 (auto-range), CT=100ms, M=100, FC=0, L=0, POL=0, ME=1 */
    if (i2c_write_reg8(fd, REG_CONFIG, 0xC610) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Conversion time ~100 ms; wait a bit longer for margin */
    usleep(150000);

    uint16_t raw;
    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* OPT3001 result register: bits [15:12] exponent, bits [11:0] mantissa */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    float lux = (float)mantissa * (0.01f * (float)(1 << exponent));

    printf("OPT3001 Lux: %.2f\n", lux);

    close(fd);
    return EXIT_SUCCESS;
}

