#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int set_serial_port(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    /* Clear O_NDELAY so reads block (we apply a VTIME timeout below). */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag &= ~PARENB;   /* No parity */
    tty.c_cflag &= ~CSTOPB;   /* One stop bit */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;       /* 8 data bits */
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); /* No software flow control */
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    /* VTIME = 5 deciseconds (0.5 s) inter-character timeout. */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_SEC;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; /* Timeout — no data available right now */
        }
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        return -1;
    }
    /* bytes_read == 0 means EOF / disconnected */
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    int fd = set_serial_port(SERIAL_PORT, BAUD_RATE);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    int result = read_data(fd, buffer, sizeof(buffer));
    if (result == -1) {
        close(fd);
        return EXIT_FAILURE;
    }
    if (result == 0) {
        fprintf(stderr, "No data received within %d second(s).\n", READ_TIMEOUT_SEC);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Received data: %s\n", buffer);
    fflush(stdout);

    close(fd);
    return EXIT_SUCCESS;
}

