#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define MIN_VALUE 0
#define MAX_VALUE 1
#define CYCLES 3
#define SLEEP_SECONDS 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int generate_random_value(void) {
    return (rand() % (MAX_VALUE - MIN_VALUE + 1)) + MIN_VALUE;
}

static int validate_value(int value) {
    if (value < MIN_VALUE || value > MAX_VALUE) {
        fprintf(stderr, "Error: Value %d is out of range [%d, %d].\n", value, MIN_VALUE, MAX_VALUE);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line 2");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    for (int i = 0; i < CYCLES && running; i++) {
        int value = generate_random_value();

        if (validate_value(value) != 0) {
            fprintf(stderr, "Invalid value generated, skipping cycle.\n");
            continue;
        }

        if (gpiod_line_set_value(line, value) < 0) {
            perror("Failed to set GPIO value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);

        for (int s = 0; s < SLEEP_SECONDS && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program finished.\n");
    return ret;
}

