}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define SLEEP_SECONDS 0.1

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int set_gpio_value(struct gpiod_line *line, int value) {
    if (value < 0 || value > 1) {
        fprintf(stderr, "Error: Invalid GPIO value %d (must be 0 or 1).\n", value);
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    while (running) {
        int value1 = rand() % 2;
        int value2 = rand() % 2;

        if (set_gpio_value(line1, value1) < 0) {
            goto cleanup;
        }
        if (set_gpio_value(line2, value2) < 0) {
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, value1, GPIO_PIN_2, value2);
        fflush(stdout);

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = (long)(SLEEP_SECONDS * 1e9);
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

