#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (int i = 0; i < 3; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int duty = (i + 1) * 100; /* 100, 200, 300 */
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d -> PWM %d\n", pins[i], duty);
        }
        fflush(stdout);
        gpioDelay(1000000); /* 1 second in microseconds */
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_17 17
#define PIN_18 18

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18;
    int ret;

    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, PIN_17);
    line18 = gpiod_chip_get_line(chip, PIN_18);
    if (!line17 || !line18) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 18)");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 17)");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 18)");
            break;
        }
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");
        usleep(50000);

        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 17)");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 18)");
            break;
        }
        printf("GPIO 17: LOW, GPIO 18: HIGH\n");
        usleep(50000);
    }

    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

