#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

static int read_w1_line(const char *path, char *buf, size_t buflen) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buf, (int)buflen, fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int get_temperature(const char *device_id, float *temperature) {
    char filepath[256];
    char line_buf[256];

    snprintf(filepath, sizeof(filepath), "%s/%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    if (read_w1_line(filepath, line_buf, sizeof(line_buf)) != 0) {
        return -1;
    }

    /* First line should end with YES */
    if (strstr(line_buf, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1;
    }

    /* Read second line */
    if (read_w1_line(filepath, line_buf, sizeof(line_buf)) != 0) {
        return -1;
    }

    char *temp_str = strstr(line_buf, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", filepath);
        return -1;
    }

    errno = 0;
    long temp_reading = strtol(temp_str + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error converting temperature string: %s\n", strerror(errno));
        return -1;
    }

    *temperature = (float)temp_reading / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    printf("Starting DS18B20 temperature readings. Press Ctrl+C to exit.\n");

    while (g_running) {
        DIR *dir = opendir(W1_DEVICES_DIR);
        if (!dir) {
            fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        struct dirent *entry;
        int devices_found = 0;

        while ((entry = readdir(dir)) != NULL && g_running) {
            if (strncmp(entry->d_name, "28-", 3) == 0) {
                float temperature;
                if (get_temperature(entry->d_name, &temperature) == 0) {
                    printf("Device %s: %.2f °C\n", entry->d_name, temperature);
                    devices_found = 1;
                } else {
                    fprintf(stderr, "Failed to read temperature from device %s\n", entry->d_name);
                }
            }
        }

        closedir(dir);

        if (!devices_found) {
            fprintf(stderr, "No DS18B20 devices found under %s\n", W1_DEVICES_DIR);
        }

        if (g_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

