#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE_NO_HOLD 0xE3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t buf[3];

    if (i2c_write_byte(fd, TRIGGER_TEMP_MEASURE_NO_HOLD) < 0) {
        return -1;
    }

    usleep(50000);

    if (i2c_read_bytes(fd, buf, 3) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    if (raw == 0 || raw == 0xFFFF) {
        fprintf(stderr, "Invalid temperature reading (stuck bits)\n");
        return -1;
    }

    raw &= 0xFFFC;
    *temperature = -46.85 + 175.72 * (float)raw / 65536.0;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature;
        if (read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        for (int i = 0; i < 60 && g_running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_4    4
#define PIN_18   18

static volatile sig_atomic_t keep_running = 1;

void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, PIN_4);
    line18 = gpiod_chip_get_line(chip, PIN_18);
    if (!line4 || !line18) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line4, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (keep_running) {
        if (gpiod_line_set_value(line4, 1) < 0 ||
            gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value high");
            break;
        }
        printf("GPIO 4 and GPIO 18 HIGH\n");
        fflush(stdout);

        usleep(50000);

        if (gpiod_line_set_value(line4, 0) < 0 ||
            gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value low");
            break;
        }
        printf("GPIO 4 and GPIO 18 LOW\n");
        fflush(stdout);

        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line4) gpiod_line_release(line4);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-toggle", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Failed to request output: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line2, 1) < 0 || gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set high: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d HIGH, GPIO %d HIGH\n", GPIO_2, GPIO_3);
        fflush(stdout);

        sleep(INTERVAL_SEC);
        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0 || gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set low: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d LOW, GPIO %d LOW\n", GPIO_2, GPIO_3);
        fflush(stdout);

        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL       0x2D
#define DATA_FORMAT     0x31
#define DATAX0          0x32

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    while (running) {
        if (write(fd, (uint8_t[]){DATAX0}, 1) != 1) {
            perror("write register pointer");
            break;
        }
        ssize_t n = read(fd, buf, 6);
        if (n != 6) {
            fprintf(stderr, "read failed: %s\n", strerror(errno));
            break;
        }

        int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        fflush(stdout);

        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define CYCLES 50
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting %d cycles on GPIO %d...\n", CYCLES, GPIO_LINE);

    for (int i = 0; i < CYCLES && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE, val);
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

