#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_17 17
#define DHT22_PIN_22 22
#define DHT22_PIN_23 23
#define DHT22_PIN_24 24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    struct timespec ts_start, ts_now;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int val;
    int last_val = 1;
    int timeout;

    /* Send start signal: pull low for >= 1ms, then high */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input; DHT22 will pull low for ~80us response */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    timeout = 0;
    while (1) {
        val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        if ((ts_now.tv_sec - ts_start.tv_sec) * 1000 + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 > 100) {
            return -1; /* Device not responding */
        }
        usleep(1);
    }

    /* Wait for high (end of response) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    timeout = 0;
    while (1) {
        val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        if ((ts_now.tv_sec - ts_start.tv_sec) * 1000 + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 > 100) {
            return -1;
        }
        usleep(1);
    }

    /* Read 40 bits */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Wait for low-to-high transition (start of bit) */
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        timeout = 0;
        while (1) {
            val = gpiod_line_get_value(line);
            if (val < 0) return -1;
            if (val == 1) break;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            if ((ts_now.tv_sec - ts_start.tv_sec) * 1000 + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 > 100) {
                return -1;
            }
            usleep(1);
        }

        /* Measure high duration: ~26-28us = '0', ~70us = '1' */
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        timeout = 0;
        while (1) {
            val = gpiod_line_get_value(line);
            if (val < 0) return -1;
            if (val == 0) break;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            if ((ts_now.tv_sec - ts_start.tv_sec) * 1000 + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 > 100) {
                return -1;
            }
            usleep(1);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long dur = (ts_now.tv_sec - ts_start.tv_sec) * 1000 + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000;
        if (dur > 50) {
            data[byte_idx] |= (1 << (7 - (bit_idx % 8)));
        }

        if ((bit_idx + 1) % 8 == 0) byte_idx++;
    }

    /* Verify checksum */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *hum = (float)((data[0] << 8) | data[1]) / 10.0;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int pins[] = {DHT22_PIN_17, DHT22_PIN_22, DHT22_PIN_23, DHT22_PIN_24};
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < num_pins; i++) {
        line = gpiod_chip_get_line(chip, pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get line %d: %s\n", pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        printf("Reading DHT22 on GPIO %d...\n", pins[i]);
        fflush(stdout);

        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Error reading DHT22 on GPIO %d\n", pins[i]);
        }

        sleep(2);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int value = (i + 1) * 100; /* 100, 200, 300 */
            if (gpioPWM(pins[i], value) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d with value %d.\n", pins[i], value);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Pin %d set to PWM value: %d\n", pins[i], value);
        }
        fflush(stdout);
        time_sleep(0.5);
    }

    /* Clean shutdown */
    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

