    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line17 || !line27) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio17-toggle", 0) < 0 ||
        gpiod_line_request_output(line27, "gpio27-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0 || gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_17, GPIO_27);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line17, 0) < 0 || gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_17, GPIO_27);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line27) gpiod_line_release(line27);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

