#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_CDATAL 0x14

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), val };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t enable;
    if (i2c_read_reg8(fd, TCS34725_ENABLE, &enable) < 0) {
        fprintf(stderr, "Error: TCS34725 not responding at 0x%02X\n", TCS34725_ADDRESS);
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, enable | TCS34725_ENABLE_PON) < 0) {
        perror("power on");
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(3000);

    if (i2c_write_reg8(fd, TCS34725_ENABLE, enable | TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        perror("enable ALS");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[8];
        if (i2c_read_block(fd, TCS34725_CDATAL, data, 8) < 0) {
            perror("read color data");
            break;
        }

        uint16_t clear = (uint16_t)data[1] << 8 | data[0];
        uint16_t red   = (uint16_t)data[3] << 8 | data[2];
        uint16_t green = (uint16_t)data[5] << 8 | data[4];
        uint16_t blue  = (uint16_t)data[7] << 8 | data[6];

        printf("R: %5u, G: %5u, B: %5u, C: %5u\n", red, green, blue, clear);
        fflush(stdout);

        usleep(200000);
    }

    uint8_t cur_enable;
    if (i2c_read_reg8(fd, TCS34725_ENABLE, &cur_enable) >= 0) {
        i2c_write_reg8(fd, TCS34725_ENABLE, cur_enable & ~(TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN));
    }
    close(fd);
    return EXIT_SUCCESS;
}

