#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int ssd1306_write_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

int ssd1306_init() {
    if (ssd1306_write_command(0xAE) < 0) return -1; // Display off
    if (ssd1306_write_command(0xD5) < 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (ssd1306_write_command(0x80) < 0) return -1;
    if (ssd1306_write_command(0xA8) < 0) return -1; // Set multiplex ratio
    if (ssd1306_write_command(SSD1306_HEIGHT - 1) < 0) return -1;
    if (ssd1306_write_command(0xD3) < 0) return -1; // Set display offset
    if (ssd1306_write_command(0x00) < 0) return -1;
    if (ssd1306_write_command(0x40) < 0) return -1; // Set start line address
    if (ssd1306_write_command(0x8D) < 0) return -1; // Enable charge pump regulator
    if (ssd1306_write_command(0x14) < 0) return -1;
    if (ssd1306_write_command(0x20) < 0) return -1; // Set memory addressing mode
    if (ssd1306_write_command(0x00) < 0) return -1;
    if (ssd1306_write_command(0xA1) < 0) return -1; // Set segment re-map
    if (ssd1306_write_command(0xC8) < 0) return -1; // Set COM output scan direction
    if (ssd1306_write_command(0xDA) < 0) return -1; // Set COM pins hardware configuration
    if (ssd1306_write_command(0x12) < 0) return -1;
    if (ssd1306_write_command(0x81) < 0) return -1; // Set contrast control register
    if (ssd1306_write_command(0xCF) < 0) return -1;
    if (ssd1306_write_command(0xD9) < 0) return -1; // Set pre-charge period
    if (ssd1306_write_command(0xF1) < 0) return -1;
    if (ssd1306_write_command(0xDB) < 0) return -1; // Set VCOMH deselect level
    if (ssd1306_write_command(0x40) < 0) return -1;
    if (ssd1306_write_command(0xA4) < 0) return -1; // Entire display on
    if (ssd1306_write_command(0xA6) < 0) return -1; // Normal display (not inverted)
    if (ssd1306_write_command(0xAF) < 0) return -1; // Display on
    return 0;
}

int ssd1306_clear_display() {
    if (ssd1306_write_command(0x21) < 0) return -1; // Set column address
    if (ssd1306_write_command(0x00) < 0) return -1;
    if (ssd1306_write_command(SSD1306_WIDTH - 1) < 0) return -1;
    if (ssd1306_write_command(0x22) < 0) return -1; // Set page address
    if (ssd1306_write_command(0x00) < 0) return -1;
    if (ssd1306_write_command((SSD1306_HEIGHT / 8) - 1) < 0) return -1;

    uint8_t zeros[SSD1306_WIDTH];
    for (int i = 0; i < SSD1306_WIDTH; i++) zeros[i] = 0x00;

    for (int page = 0; page < SSD1306_HEIGHT / 8; page++) {
        uint8_t buf[SSD1306_WIDTH + 1];
        buf[0] = 0x40;
        for (int col = 0; col < SSD1306_WIDTH; col++) buf[col + 1] = zeros[col];
        if (write(i2c_fd, buf, SSD1306_WIDTH + 1) != SSD1306_WIDTH + 1) return -1;
    }
    return 0;
}

int ssd1306_draw_string(const char *str, int x, int y) {
    (void)x; (void)y;
    // Simple ASCII-only print at current cursor position
    uint8_t buf[SSD1306_WIDTH + 1];
    buf[0] = 0x40;
    for (int i = 0; i < SSD1306_WIDTH; i++) {
        if (str[i] != '\0') buf[i + 1] = str[i];
        else buf[i + 1] = ' ';
    }
    if (write(i2c_fd, buf, SSD1306_WIDTH + 1) != SSD1306_WIDTH + 1) return -1;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (ssd1306_init() < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        if (ssd1306_clear_display() < 0) break;
        if (ssd1306_draw_string("Hello, World!", 0, 0) < 0) break;
        usleep(100000);
    }

    ssd1306_write_command(0xAE);
    close(i2c_fd);
    return 0;
}

