#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define VCC_PIN     24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *vcc = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc  = gpiod_chip_get_line(chip, VCC_PIN);
    if (!trig || !echo || !vcc) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Request trigger line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Request echo line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(vcc, "hc-sr04-vcc", 1) < 0) {
        fprintf(stderr, "Request VCC line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        long long t0, t1, elapsed_us;

        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Set trigger low failed: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Set trigger high failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Set trigger low failed: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge (timeout ~20 ms) */
        t0 = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Read echo failed: %s\n", strerror(errno));
                running = 0;
                break;
            }
            if (val == 1) {
                break;
            }
            if (now_ns() - t0 > 20000000LL) {
                printf("Timeout waiting for echo rising edge.\n");
                fflush(stdout);
                goto next_iter;
            }
            usleep(100);
        }
        if (!running) break;

        /* Measure echo pulse width (timeout ~30 ms) */
        t0 = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Read echo failed: %s\n", strerror(errno));
                running = 0;
                break;
            }
            if (val == 0) {
                t1 = now_ns();
                elapsed_us = (t1 - t0) / 1000LL;
                float distance = (elapsed_us * 0.0343f) / 2.0f;
                printf("Distance: %.2f cm\n", distance);
                fflush(stdout);
                break;
            }
            if (now_ns() - t0 > 30000000LL) {
                printf("Timeout waiting for echo falling edge.\n");
                fflush(stdout);
                goto next_iter;
            }
            usleep(100);
        }
        if (!running) break;

    next_iter:
        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc)  gpiod_line_release(vcc);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

