    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, 0xD0, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }

    /* Reset */
    if (i2c_write_reg8(fd, 0xE0, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    /* Read calibration data */
    uint8_t calib[24];
    for (int i = 0; i < 24; i++) {
        if (i2c_read_reg8(fd, 0x88 + i, &calib[i]) < 0) {
            fprintf(stderr, "Error: Failed to read calibration data: %s\n", strerror(errno));
            return -1;
        }
    }

    /* Oversampling x1, normal mode */
    if (i2c_write_reg8(fd, 0xF4, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_read(int fd, float *temp, float *press, float *hum) {
    uint8_t raw[8];
    for (int i = 0; i < 8; i++) {
        if (i2c_read_reg8(fd, 0xF7 + i, &raw[i]) < 0) {
            fprintf(stderr, "Error: Failed to read data registers: %s\n", strerror(errno));
            return -1;
        }
    }

    int32_t adc_P = (raw[0] << 12) | (raw[1] << 4) | (raw[2] >> 4);
    int32_t adc_T = (raw[3] << 12) | (raw[4] << 4) | (raw[5] >> 4);
    int32_t adc_H = (raw[6] << 8) | raw[7];

    /* Placeholder compensation (real BME280 needs calibration) */
    *temp = adc_T / 100.0f;
    *press = adc_P / 100.0f;
    *hum = adc_H / 1000.0f;
    return 0;
}

