#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 vs GND, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000 | (0x4000) | (0x0000) | (0x0080) | (0x0003)

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading config register */
    uint16_t cfg_check;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t cfg = ADS1115_CFG_BASE | (1 << 15); /* assert OS bit to start conversion */
        if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) {
            fprintf(stderr, "Error writing config: %s\n", strerror(errno));
            break;
        }

        usleep(10000); /* 10 ms > 1/128 s conversion time */

        uint16_t raw;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Error reading conversion: %s\n", strerror(errno));
            break;
        }

        int16_t signed_val = (int16_t)raw;
        printf("AIN0: %d\n", signed_val);
        fflush(stdout);

        usleep(100000); /* 0.2 s between samples */
    }

    close(fd);
    return EXIT_SUCCESS;
}

