        int16_t gx = (int16_t)((buf[8] << 8) | buf[9]);
        int16_t gy = (int16_t)((buf[10] << 8) | buf[11]);
        int16_t gz = (int16_t)((buf[12] << 8) | buf[13]);

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);

        usleep(10000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define PERIOD_US 50000

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error: read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line, val ? 0 : 1) < 0) {
            fprintf(stderr, "Error: write failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, val ? 0 : 1);
        fflush(stdout);
        usleep(PERIOD_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LCD_ADDR 0x27

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x02
#define LCD_BLINKOFF 0x01
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00
#define LCD_4BITMODE 0x00

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_nibble(int fd, uint8_t nibble, uint8_t rs) {
    uint8_t data = (nibble & 0xF0) | rs | 0x0C;
    if (i2c_write_byte(fd, data) < 0) return -1;
    if (i2c_write_byte(fd, data & 0x0F) < 0) return -1;
    usleep(100);
    return 0;
}

static int lcd_send_command(int fd, uint8_t cmd) {
    if (lcd_send_nibble(fd, cmd & 0xF0, 0) < 0) return -1;
    if (lcd_send_nibble(fd, (cmd << 4) & 0xF0, 0) < 0) return -1;
    return 0;
}

static int lcd_send_data(int fd, uint8_t data) {
    if (lcd_send_nibble(fd, data & 0xF0, 0x01) < 0) return -1;
    if (lcd_send_nibble(fd, (data << 4) & 0xF0, 0x01) < 0) return -1;
    return 0;
}

static int lcd_init(int fd) {
    usleep(50000);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    usleep(5000);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    usleep(150);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    usleep(150);
    if (lcd_send_nibble(fd, 0x20, 0) < 0) return -1;
    usleep(150);

    if (lcd_send_command(fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    if (lcd_send_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    if (lcd_send_command(fd, LCD_CLEARDISPLAY) < 0) return -1;
    usleep(2000);
    if (lcd_send_command(fd, LCD_ENTRYMODESET | 0x02) < 0) return -1;
    return 0;
}

static int lcd_clear(int fd) {
    return lcd_send_command(fd, LCD_CLEARDISPLAY);
}

static int lcd_set_cursor(int fd, int col, int row) {
    int addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    return lcd_send_command(fd, LCD_SETDDRAMADDR | addr);
}

static int lcd_print(int fd, const char *str) {
    while (*str) {
        if (lcd_send_data(fd, (uint8_t)*str) < 0) return -1;
        str++;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (lcd_init(fd) < 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (lcd_clear(fd) < 0) break;
        if (lcd_set_cursor(fd, 0, 0) < 0) break;
        if (lcd_print(fd, "Hello World!") < 0) break;
        if (lcd_set_cursor(fd, 0, 1) < 0) break;
        if (lcd_print(fd, "Raspberry Pi") < 0) break;
        sleep(10);
    }

    lcd_clear(fd);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define WHO_AM_I_VAL 0x68

static volatile sig_atomic_t running = 1;

static void sigh(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sigh;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "PWR_MGMT_1 write failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    usleep(100000);

    for (int i = 0; i < 100 && running; i++) {
        uint8_t buf[14];
        uint8_t reg = 0x3B;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Failed to set read register: %s\n", strerror(errno));
            break;
        }
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "Short read: %s\n", strerror(errno));
            break;
        }

        int16_t ax = (buf[0] << 8) | buf[1];
        int16_t ay = (buf[2] << 8) | buf[3];
        int16_t az = (buf[4] << 8) | buf[5];
        int16_t tx = (buf[8] << 8) | buf[9];
        int16_t ty = (buf[10] << 8) | buf[11];
        int16_t tz = (buf[12] << 8) | buf[13];

        printf("Accel X: %d, Y: %d, Z: %d, Temp: %d, Gyro X: %d, Y: %d, Z: %d\n",
               ax, ay, az, tx, ty, tz);
        fflush(stdout);
        usleep(10000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_14   14
#define GPIO_PIN_15   15
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int set_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_PIN_14);
    if (!line14) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_PIN_14, strerror(errno));
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_PIN_15);
    if (!line15) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_PIN_15, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line14, "digital-output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n",
                GPIO_PIN_14, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, "digital-output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n",
                GPIO_PIN_15, strerror(errno));
        goto cleanup;
    }

    while (running) {
        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));

        int val14 = (int)(now % 2);
        int val15 = (int)((now / 2) % 2);

        if (set_output(line14, val14) < 0 || set_output(line15, val15) < 0) {
            fprintf(stderr, "[%s] Error writing to GPIO lines.\n", ts);
        } else {
            printf("[%s] GPIO %d: %d, GPIO %d: %d\n",
                   ts, GPIO_PIN_14, val14, GPIO_PIN_15, val15);
            fflush(stdout);
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line14) gpiod_line_release(line14);
    if (line15) gpiod_line_release(line15);
    if (chip)   gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/reading"
#define SLEEP_INTERVAL_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

/* Read a single sensor value from a simulated device.
 * Returns 0 on success, -1 on error. */
static int read_sensor_value(int *value) {
    /* Simulate a device read with a 5% chance of failure. */
    if (rand() % 20 == 0) {
        return -1;
    }
    *value = rand() % 100;
    return 0;
}

/* Validate the sensor reading. Returns 0 if valid, -1 otherwise. */
static int validate_sensor_reading(int value) {
    if (value < 0 || value > 100) {
        fprintf(stderr, "Error: Invalid sensor reading: %d\n", value);
        return -1;
    }
    return 0;
}

/* Format the sensor reading into a JSON string. */
static char *format_json_payload(int value) {
    char *payload = malloc(64);
    if (payload == NULL) {
        perror("malloc");
        return NULL;
    }
    snprintf(payload, 64, "{\"sensor_id\": \"sensor1\", \"value\": %d}", value);
    return payload;
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;
    int sensor_value;
    char *payload;

    srand(time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if ((rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS,
                                MQTT_CLIENT_ID,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_sensor_value(&sensor_value) != 0) {
            fprintf(stderr, "Error reading sensor value\n");
            break;
        }

        if (validate_sensor_reading(sensor_value) != 0) {
            fprintf(stderr, "Sensor reading validation failed\n");
            break;
        }

        payload = format_json_payload(sensor_value);
        if (payload == NULL) {
            fprintf(stderr, "Failed to format JSON payload\n");
            break;
        }

        pubmsg.payload = payload;
        pubmsg.payloadlen = (int)strlen(payload);
        pubmsg.qos = 0;
        pubmsg.retained = 0;

        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
            free(payload);
            break;
        }

        free(payload);

        usleep(SLEEP_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

