#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define NUM_SENSORS  3

#define SPEED_OF_SOUND_CM_S 34300.0
#define MIN_DISTANCE_CM     2.0
#define MAX_DISTANCE_CM     400.0
#define TIMEOUT_US          30000   /* 30 ms timeout (~5 m round trip) */
#define SETTLE_US           200000  /* 200 ms settle time */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

/* Busy-wait for echo line to reach the requested level, with a timeout.
 * Returns 0 on success, -1 on timeout. */
static int wait_level(struct gpiod_line *line, int level, long timeout_us)
{
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    for (;;) {
        if (gpiod_line_get_value(line) == level)
            return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000L +
                       (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed >= timeout_us)
            return -1;
    }
}

/* Measure distance in cm. Returns -1.0 on error/timeout. */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge */
    if (wait_level(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0;
    }

    struct timespec t_rise;
    clock_gettime(CLOCK_MONOTONIC, &t_rise);

    /* Wait for echo falling edge */
    if (wait_level(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0;
    }

    struct timespec t_fall;
    clock_gettime(CLOCK_MONOTONIC, &t_fall);

    long diff_ns = (t_fall.tv_sec - t_rise.tv_sec) * 1000000000L +
                   (t_fall.tv_nsec - t_rise.tv_nsec);
    double duration_s = (double)diff_ns / 1e9;
    float distance = (float)(duration_s * SPEED_OF_SOUND_CM_S / 2.0);

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }
    return distance;
}

int main(void)
{
    const char *chipname = "gpiochip0";
    unsigned int trig_pins[NUM_SENSORS] = {17, 22, 27};
    unsigned int echo_pins[NUM_SENSORS]  = {27, 18, 23}; /* corrected BCM */

    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", chipname, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig_lines[NUM_SENSORS];
    struct gpiod_line *echo_lines[NUM_SENSORS];

    for (int i = 0; i < NUM_SENSORS; i++) {
        trig_lines[i] = gpiod_chip_get_line(chip, trig_pins[i]);
        echo_lines[i] = gpiod_chip_get_line(chip, echo_pins[i]);
        if (!trig_lines[i] || !echo_lines[i]) {
            fprintf(stderr, "Failed to get GPIO lines for sensor %d: %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_output(trig_lines[i], "hcsr04-trig", 0) < 0) {
            fprintf(stderr, "Request trigger line %u failed: %s\n",
                    trig_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(echo_lines[i], "hcsr04-echo") < 0) {
            fprintf(stderr, "Request echo line %u failed: %s\n",
                    echo_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_SENSORS && running; i++) {
            float d = measure_distance(trig_lines[i], echo_lines[i]);
            if (d >= 0.0f)
                printf("Sensor %d: %.2f cm\n", i, d);
            else
                printf("Sensor %d: read failed\n", i);
        }
        usleep(100000); /* 100 ms between cycles */
    }

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (trig_lines[i])
            gpiod_line_release(trig_lines[i]);
        if (echo_lines[i])
            gpiod_line_release(echo_lines[i]);
    }
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

