#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value low */
    if (gpiod_line_request_output(line, "gpio17-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d set to LOW\n", GPIO_LINE);

    while (running) {
        sleep(1);
    }

    /* Ensure line is left in a defined state before release */
    gpiod_line_set_value(line, 0);
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

