#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define DEFAULT_MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define DEFAULT_MQTT_CLIENT_ID     "rpi_sensor_client"
#define DEFAULT_MQTT_TOPIC         "sensor/reading"
#define DEFAULT_GPIO_PIN           4

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(int argc, char *argv[]) {
    const char *mqtt_broker_address = DEFAULT_MQTT_BROKER_ADDRESS;
    const char *mqtt_client_id      = DEFAULT_MQTT_CLIENT_ID;
    const char *mqtt_topic          = DEFAULT_MQTT_TOPIC;
    int gpio_pin                    = DEFAULT_GPIO_PIN;

    int opt;
    while ((opt = getopt(argc, argv, "b:c:t:p:")) != -1) {
        switch (opt) {
            case 'b': mqtt_broker_address = optarg; break;
            case 'c': mqtt_client_id      = optarg; break;
            case 't': mqtt_topic          = optarg; break;
            case 'p': gpio_pin            = atoi(optarg); break;
            default:
                fprintf(stderr,
                        "Usage: %s [-b broker] [-c client_id] [-t topic] [-p pin]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", gpio_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    if ((rc = MQTTClient_create(&client, mqtt_broker_address,
                                mqtt_client_id,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL))
        != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_create failed: %s\n",
                MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession      = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_connect failed: %s\n",
                MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d.\n", gpio_pin);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char payload[32];
    snprintf(payload, sizeof(payload), "%d", level);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload   = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos       = 0;
    pubmsg.retained  = 0;

    MQTTClient_deliveryToken token;
    if ((rc = MQTTClient_publishMessage(client, mqtt_topic, &pubmsg, &token))
        != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_publishMessage failed: %s\n",
                MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Published: %s -> %s\n", payload, mqtt_topic);

    MQTTClient_waitForCompletion(client, token, 1000);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (hardware not available).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d with value %d.\n", PWM_PIN, i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle set to %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            sleep(1);
        }
        for (int i = PWM_RANGE; i >= 0 && running; i--) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d with value %d.\n", PWM_PIN, i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle set to %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            sleep(1);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  100000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        long long t0, t1, elapsed;

        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger high failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low failed: %s\n", strerror(errno));
            break;
        }

        t0 = now_us();
        while (running) {
            int v = gpiod_line_get_value(echo);
            if (v < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                goto cleanup;
            }
            if (v == 1) break;
            if (now_us() - t0 > TIMEOUT_US) {
                printf("Timeout waiting for echo rising edge.\n");
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        t1 = now_us();
        while (running) {
            int v = gpiod_line_get_value(echo);
            if (v < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                goto cleanup;
            }
            if (v == 0) break;
            if (now_us() - t1 > TIMEOUT_US) {
                printf("Timeout waiting for echo falling edge.\n");
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        elapsed = now_us() - t0;
        float distance = (elapsed / 1000000.0f) * 34300.0f / 2.0f;

        if (distance < 2.0f || distance > 400.0f) {
            printf("Distance out of range: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 4
static const int pins[NUM_PINS] = {17, 18, 22, 23};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int value = (i + 1) * 50; /* 50, 100, 150, 200 */
            if (gpioPWM(pins[i], value) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Pin %d set to PWM value: %d\n", pins[i], value);
        }
        fflush(stdout);
        time_sleep(0.1);
    }

    /* Clean shutdown: turn off all outputs before releasing */
    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_CLIENT_ID      "rpi_sensor_publisher"
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC          "/sensors/temperature"
#define DEVICE_PATH         "/dev/ttyS0"
#define BAUD_RATE           9600
#define READ_TIMEOUT_MS     2000
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sensor_data(const char *device_path, char *buffer, size_t buffer_size) {
    FILE *fp = fopen(device_path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening device %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    size_t total_read = 0;
    int retries = 0;
    while (total_read < buffer_size - 1 && retries < MAX_RETRIES) {
        int c = fgetc(fp);
        if (c == EOF) {
            if (feof(fp)) break;
            if (errno == EINTR) { retries++; continue; }
            fprintf(stderr, "Read error on %s: %s\n", device_path, strerror(errno));
            fclose(fp);
            return -1;
        }
        if (c == '\n' || c == '\r') continue;
        buffer[total_read++] = (char)c;
    }
    buffer[total_read] = '\0';
    fclose(fp);

    if (total_read == 0) {
        fprintf(stderr, "No data received from %s\n", device_path);
        return -1;
    }
    return 0;
}

static int validate_sensor_reading(const char *data) {
    if (!data || strlen(data) == 0) return -1;
    for (int i = 0; data[i]; i++) {
        if ((data[i] < '0' || data[i] > '9') && data[i] != '.' && data[i] != '-') {
            fprintf(stderr, "Invalid character in reading: %c\n", data[i]);
            return -1;
        }
    }
    return 0;
}

static int publish_sensor_data(MQTTClient client, const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(client, NULL, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char sensor_data[256];
    if (read_sensor_data(DEVICE_PATH, sensor_data, sizeof(sensor_data)) != 0) {
        fprintf(stderr, "Sensor read failed; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (validate_sensor_reading(sensor_data) != 0) {
        fprintf(stderr, "Sensor data validation failed; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char payload[512];
    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"value\": %s}",
             timestamp, sensor_data);

    if (publish_sensor_data(client, MQTT_TOPIC, payload) != 0) {
        fprintf(stderr, "Publish failed; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Published: %s\n", payload);

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "ads1115_publisher"
#define MQTT_TOPIC "sensor/ads1115"

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int read_ads1115(int i2c_handle, int channel) {
    if (channel < 0 || channel > 3) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC0 | (channel << 4);
    config[2] = 0x83;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    gpioDelay(10000);

    char reg[1] = {CONVERSION_REG};
    if (i2cWriteDevice(i2c_handle, reg, 1) != 0) {
        fprintf(stderr, "Error setting conversion register pointer\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if ((rc = MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Connected to MQTT broker\n");

    for (int i = 0; i < 10 && running; i++) {
        int reading = read_ads1115(i2c_handle, 0);
        if (reading == -1) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        char payload[32];
        snprintf(payload, sizeof(payload), "%d", reading);

        pubmsg.payload = payload;
        pubmsg.payloadlen = strlen(payload);
        pubmsg.qos = 0;
        pubmsg.retained = 0;

        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
            break;
        }

        printf("Published reading: %s\n", payload);
        sleep(1);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error: cannot get GPIO %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error: cannot get GPIO %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d high: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d low: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d HIGH, GPIO %d LOW\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(DELAY_US);

        if (!running) break;

        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d low: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d high: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d LOW, GPIO %d HIGH\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

