                fprintf(stderr, "Error: failed to write GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d -> %s\n", pins[i], val ? "HIGH" : "LOW");
        }
        fflush(stdout);

        time_sleep(0.5);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val == target) return 0;
        if (val < 0) return -1;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > timeout_us) return 1;
    }
    return 1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int laststate = 1;
    int counter = 0;
    int bitidx = 0;

    /* Start signal: pull low for >= 1ms, then high */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    /* Wait for sensor to pull low (response) */
    if (wait_for_level(line, 0, 1000) != 0) return -1;
    if (wait_for_level(line, 1, 1000) != 0) return -1;
    if (wait_for_level(line, 0, 1000) != 0) return -1;

    /* Read 40 bits */
    while (bitidx < 40 && running) {
        if (wait_for_level(line, 1, 1000) != 0) return -1;
        counter = 0;
        while (gpiod_line_get_value(line) == 1 && counter < 100 && running) {
            counter++;
            usleep(1);
        }
        if (!running) break;
        if (counter > 10) {
            data[bitidx / 8] <<= 1;
            if (counter > 30) data[bitidx / 8] |= 1;
            bitidx++;
        }
    }

    if (bitidx < 40) return -1;

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    if (read_dht22(line, &temperature, &humidity) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        ret = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "DHT22 read failed (sensor absent or bus error)\n");
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
