    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value high");
                goto cleanup;
            }
        }
        printf("GPIO 17, 23, 24, 25 HIGH\n");
        fflush(stdout);

        sleep(10);

        if (!running)
            break;

        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value low");
                goto cleanup;
