#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 4

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 4 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value low */
    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d set to LOW\n", GPIO_LINE);
    fflush(stdout);

    while (running) {
        sleep(2);
        if (!running) break;

        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            goto cleanup;
        }
        printf("GPIO %d set to HIGH\n", GPIO_LINE);
        fflush(stdout);

        sleep(2);
        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("GPIO %d set to LOW\n", GPIO_LINE);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6

static const unsigned int pins[NUM_PINS] = {4, 17, 22, 23, 24, 27};
static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS && running; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u\n", pins[i]);
            goto cleanup;
        }
