    if (!running)
        goto cleanup;

    printf("GPIO 4: LOW\n");
    printf("GPIO 17: LOW\n");
    printf("GPIO 22: LOW\n");
    printf("GPIO 23: LOW\n");
    printf("GPIO 24: LOW\n");
    printf("GPIO 27: LOW\n");

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
