#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4    4
#define GPIO_17   17

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_4, strerror(errno));
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line4, "gpio4-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_4, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line17, "gpio17-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_17, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and GPIO %d set to LOW\n", GPIO_4, GPIO_17);
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually so we can report each error */
    if (line4) {
        if (gpiod_line_release(line4) < 0)
            perror("Warning: failed to release line 4");
    }
    if (line17) {
        if (gpiod_line_release(line17) < 0)
            perror("Warning: failed to release line 17");
    }
    if (chip) {
        if (gpiod_chip_close(chip) < 0)
            perror("Warning: failed to close chip");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio17-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error: read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line, val ? 0 : 1) < 0) {
            fprintf(stderr, "Error: write failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO 17 set to %d\n", val ? 0 : 1);
        fflush(stdout);
        usleep(INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

