#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8574_ADDR 0x20

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero write to confirm the device is present */
    if (i2c_write_byte(fd, 0x00) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    const char *msg = "Hello";
    size_t len = strlen(msg);

    for (size_t i = 0; i < len && running; i++) {
        uint8_t c = (uint8_t)(msg[i]);
        /* PCF8574 bit layout: [RS][RW][EN][BL][D4 D5 D6 D7] */
        /* RS=1 (data), RW=0 (write), EN=1 (strobe high) */
        uint8_t hi = 0x0D | ((c >> 4) & 0x0F);
        uint8_t lo = 0x09 | ((c & 0x0F) & 0x0F);

        if (i2c_write_byte(fd, hi) < 0) break;
        usleep(1000);
        if (i2c_write_byte(fd, lo) < 0) break;
        usleep(1000);
        /* Strobe low to latch data */
        if (i2c_write_byte(fd, lo & 0xF0) < 0) break;
        usleep(1000);
    }

    /* Clear display */
    if (running) {
        if (i2c_write_byte(fd, 0x01) < 0) {}
        usleep(2000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

