#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_S 34300.0
#define MAX_DISTANCE_CM     400.0
#define TIMEOUT_US          30000   /* 30 ms timeout (~5 m round trip) */

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(50);

    printf("HC-SR04 ranging started (trigger=GPIO%d, echo=GPIO%d). Press Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    while (running) {
        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            goto cleanup;
        }

        long long t_start = now_us();
        if (t_start < 0) {
            fprintf(stderr, "Clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Wait for echo rising edge */
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (!running) break;
        } while (val == 0);

        if (!running) break;

        long long t_rise = now_us();
        if (t_rise < 0) {
            fprintf(stderr, "Clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Wait for echo falling edge */
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (!running) break;
        } while (val == 1);

        if (!running) break;

        long long t_fall = now_us();
        if (t_fall < 0) {
            fprintf(stderr, "Clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        long long elapsed = t_fall - t_rise;
        if (elapsed > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo (no object detected or sensor absent)\n");
            continue;
        }

        double distance = (elapsed / 1000000.0) * SPEED_OF_SOUND_CM_S / 2.0;

        if (distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range (%.2f cm)\n", distance);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

