    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = rand() % 2;
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
        }

        if (!valid_reading(values)) {
            fprintf(stderr, "Invalid reading, aborting.\n");
            goto cleanup;
        }

        report(values);

        for (int s = 0; s < PERIOD_SEC && running; s++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++)
        if (lines[i])
            gpiod_line_release(lines[i]);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

