#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW  0x06
#define READ_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd_high, uint8_t cmd_low) {
    uint8_t buf[2] = {cmd_high, cmd_low};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31_read_measurement(int fd, float *temperature, float *humidity) {
    if (i2c_write_cmd(fd, MEASURE_CMD_HIGH, MEASURE_CMD_LOW) < 0) {
        return -1;
    }

    usleep(20000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, sizeof(data)) < 0) {
        return -1;
    }

    uint16_t raw_temperature = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_humidity   = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)raw_temperature / 65535.0f);
    *humidity    = 100.0f * (float)raw_humidity / 65535.0f;

    if (*humidity > 100.0f) *humidity = 100.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;

    if (*temperature < -40.0f || *temperature > 125.0f ||
        *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Invalid sensor reading: T=%.2f C, H=%.2f %%\n",
                *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SHT31_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;

        if (sht31_read_measurement(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read measurement.\n");
        }

        for (int i = 0; i < READ_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

