                GPIO_2, GPIO_3, strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line2, 1) < 0 || gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO high: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d HIGH\n", GPIO_2, GPIO_3);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0 || gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO low: %s\n", strerror(errno));
            goto cleanup;
