#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 3
#define CONSUMER "gpio_cycle"

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    const unsigned int pins[NUM_PINS] = {2, 3, 17};
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on most Raspberry Pi models) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines for each pin */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    /* Request each line as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Starting 3-cycle blink sequence on GPIO 2, 3, 17...\n");

    /* 3 full cycles: high for 1 s, low for 1 s */
    for (int cycle = 0; cycle < 3 && running; cycle++) {
        /* High phase */
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set line %u high\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Cycle %d: HIGH\n", cycle + 1);
        fflush(stdout);
        sleep(1);

        if (!running) break;

        /* Low phase */
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set line %u low\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Cycle %d: LOW\n", cycle + 1);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually, then close chip */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Program finished.\n");
    return ret;
}

