#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 24
#define PERIOD_US 50000

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 24 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value low */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting digital output toggling on GPIO %d...\n", GPIO_LINE);

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value high");
            break;
