}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_FILE "captured_image.jpg"

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening video device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *buffer = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!buffer) {
        perror("Memory allocation failed");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    ssize_t bytes_read = read(fd, buffer, IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (bytes_read < 0) {
        perror("Error reading from device");
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CAPTURE_FILE, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, 1, bytes_read, fp) != (size_t)bytes_read) {
        perror("Error writing to file");
        fclose(fp);
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);
    free(buffer);
    ioctl(fd, VIDIOC_STREAMOFF, &type);
    close(fd);

    printf("Image captured and saved as %s\n", CAPTURE_FILE);
    return EXIT_SUCCESS;
}

#include <stdio.h>
