#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int red = 255;
    int green = 0;
    int blue = 0;

    for (int i = 0; i < 3 && running; i++) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write high to GPIO %d.\n", LED_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        time_sleep(0.005);

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write low to GPIO %d.\n", LED_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        time_sleep(0.005);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

