#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>

#define W1_DEVICE_PATH "/sys/bus/w1/devices/28-0000067c7e2b/w1_slave"
#define NUM_READINGS 3
#define SLEEP_SECONDS 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int read_temperature(const char *path, float *temperature) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("Error opening w1_slave file");
        return -1;
    }

    char line1[256];
    char line2[256];

    if (!fgets(line1, sizeof(line1), fp)) {
        perror("Error reading first line");
        fclose(fp);
        return -1;
    }
    if (!fgets(line2, sizeof(line2), fp)) {
        perror("Error reading second line");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }

    long temp_milli = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_milli / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    printf("Starting DS18B20 temperature readings...\n");

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float temperature;
        if (read_temperature(W1_DEVICE_PATH, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            return EXIT_FAILURE;
        }

        if (i < NUM_READINGS - 1) {
            sleep(SLEEP_SECONDS);
        }
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

