#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define VCC_PIN     24

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MAX_DISTANCE_CM         400.0
#define TIMEOUT_US              30000
#define LOOP_DELAY_MS           100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    long long start_time = now_us();
    if (start_time < 0) {
        return -1.0;
    }

    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1.0;
        if (now_us() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
    }

    long long pulse_start = now_us();
    if (pulse_start < 0) {
        return -1.0;
    }

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1.0;
        if (now_us() - pulse_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
    }

    long long pulse_end = now_us();
    if (pulse_end < 0) {
        return -1.0;
    }

    long long pulse_duration = pulse_end - pulse_start;
    double distance = (double)pulse_duration * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *vcc  = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc  = gpiod_chip_get_line(chip, VCC_PIN);

    if (!trig || !echo || !vcc) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(vcc, "hc-sr04-vcc", 1) < 0) {
        fprintf(stderr, "Failed to request VCC line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 sensor initialized. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance(trig, echo);
        if (distance >= 0.0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to measure distance.\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc)  gpiod_line_release(vcc);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

