#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    unsigned gpio_pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(gpio_pins) / sizeof(gpio_pins[0]); ++i) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %u as output\n", gpio_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor_data(int *data) {
    FILE *fp = popen("python3 sensor.py", "r");
    if (fp == NULL) {
        perror("popen failed");
        return -1;
    }

    char buffer[64];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read from sensor script");
        pclose(fp);
        return -1;
    }

    if (pclose(fp) != 0) {
        fprintf(stderr, "Warning: sensor script exited with non-zero status\n");
    }

    if (sscanf(buffer, "%d", data) != 1) {
        fprintf(stderr, "Error: Invalid sensor data format: %s", buffer);
        return -1;
    }

    return 0;
}

static int validate_sensor_data(int data) {
    return (data >= 0 && data <= 100);
}

static int map_sensor_to_pwm(int sensor_value) {
    return (int)(((float)sensor_value / 100.0f) * 255.0f);
}

static void set_pwm_outputs(int pwm_value) {
    unsigned gpio_pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(gpio_pins) / sizeof(gpio_pins[0]); ++i) {
        if (gpioPWM(gpio_pins[i], pwm_value) != 0) {
            fprintf(stderr, "Warning: Failed to set PWM on GPIO %u\n", gpio_pins[i]);
        }
    }
}

static void cleanup_gpio(void) {
    unsigned gpio_pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(gpio_pins) / sizeof(gpio_pins[0]); ++i) {
        gpioPWM(gpio_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_data;
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in 0.1 seconds...\n");
            usleep(100000);
            continue;
        }

        if (!validate_sensor_data(sensor_data)) {
            fprintf(stderr, "Invalid sensor data: %d. Retrying in 0.1 seconds...\n", sensor_data);
            usleep(100000);
            continue;
        }

        int pwm_value = map_sensor_to_pwm(sensor_data);
        set_pwm_outputs(pwm_value);

        printf("Sensor Data: %d, PWM Value: %d\n", sensor_data, pwm_value);
        fflush(stdout);

        usleep(100000);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

