#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (running) {
        if (gpiod_line_get_value(line) == target) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed > timeout_us) return -1;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i, j;

    /* Start signal: pull low for >= 1ms, then high */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input; DHT22 will pull low */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    /* Wait for sensor response: ~80us low then ~80us high */
    if (wait_for_level(line, 0, 1000) < 0) return -1;
    if (wait_for_level(line, 1, 1000) < 0) return -1;
    if (wait_for_level(line, 0, 1000) < 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            /* Low pulse (~50us) */
            if (wait_for_level(line, 1, 1000) < 0) return -1;
            /* High pulse: ~26-28us = '0', ~70us = '1' */
            struct timespec t0, t1;
            clock_gettime(CLOCK_MONOTONIC, &t0);
            if (wait_for_level(line, 0, 1000) < 0) return -1;
            clock_gettime(CLOCK_MONOTONIC, &t1);
            long high_us = (t1.tv_sec - t0.tv_sec) * 1000000L + (t1.tv_nsec - t0.tv_nsec) / 1000L;
            if (high_us > 50) data[i] |= (1 << j);
        }
    }

    /* Checksum */
    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    printf("DHT22 sensor reader started on GPIO %d. Press Ctrl+C to exit.\n", DHT22_PIN);

    for (int cycle = 0; cycle < MAX_CYCLES && running; cycle++) {
        float temp, hum;
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", cycle + 1, temp, hum);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read valid data from DHT22.\n", cycle + 1);
        }
        sleep(2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    printf("Exiting.\n");
    return ret;
}

