#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int rc = gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set mode on pin %d: %s\n", PWM_PIN_1, pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set mode on pin %d: %s\n", PWM_PIN_2, pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioPWM(PWM_PIN_1, 128);
    if (rc != 0) {
        fprintf(stderr, "Failed to set PWM on pin %d: %s\n", PWM_PIN_1, pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioPWM(PWM_PIN_2, 128);
    if (rc != 0) {
