#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_PINS 7
#define CYCLES 100
#define PERIOD_MS 500

static const unsigned int pins[NUM_PINS] = {4, 17, 22, 23, 24, 25, 27};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int i, ret;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_request_output(lines[i], "digital-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++)
        vals[i] = 0;

    for (i = 0; i < CYCLES && running; i++) {
        for (int j = 0; j < NUM_PINS; j++) {
            ret = gpiod_line_set_value(lines[j], vals[j]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set line %u: %s\n",
                        pins[j], strerror(errno));
                goto cleanup;
            }
        }

        printf("GPIO 4=%d, 17=%d, 22=%d, 23=%d, 24=%d, 25=%d, 27=%d\n",
               vals[0], vals[1], vals[2], vals[3], vals[4], vals[5], vals[6]);
        fflush(stdout);

        for (int j = 0; j < NUM_PINS; j++)
            vals[j] = !vals[j];

        usleep(PERIOD_MS * 1000);
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return running ? EXIT_SUCCESS : EXIT_FAILURE;
}

