#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 4
static const int pins[NUM_PINS] = {4, 17, 18, 27};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int cycle = 0;
    while (running && cycle < 5) {
        printf("Cycle %d: setting pins HIGH\n", cycle + 1);
        fflush(stdout);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioWrite(pins[i], 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        for (int s = 0; s < 60 && running; s++) {
            sleep(1);
        }

        if (!running) {
            break;
        }

        printf("Cycle %d: setting pins LOW\n", cycle + 1);
        fflush(stdout);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioWrite(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        for (int s = 0; s < 60 && running; s++) {
            sleep(1);
        }

        if (running) {
            cycle++;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioWrite(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

