#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define MAX_CYCLES 3
#define CYCLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, uint32_t timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == target) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > (long)timeout_us) return 1;
    }
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i, j;

    /* Start signal: pull low for >=1ms, then high */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input; DHT22 will pull low */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    /* Wait for sensor response: ~80us low then ~80us high */
    if (wait_for_level(line, 0, 1000) != 0) return -1;
    if (wait_for_level(line, 1, 1000) != 0) return -1;
    if (wait_for_level(line, 0, 1000) != 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            /* Low pulse (~50us) */
            if (wait_for_level(line, 1, 1000) != 0) return -1;
            /* High pulse: ~26-28us = '0', ~70us = '1' */
            struct timespec t_start, t_now;
            clock_gettime(CLOCK_MONOTONIC, &t_start);
            while (1) {
                int v = gpiod_line_get_value(line);
                if (v < 0) return -1;
                if (v == 0) break;
                clock_gettime(CLOCK_MONOTONIC, &t_now);
                long us = (t_now.tv_sec - t_start.tv_sec) * 1000000L + (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
                if (us > 1000) return -1;
            }
            struct timespec t_high_start, t_high_now;
            clock_gettime(CLOCK_MONOTONIC, &t_high_start);
            while (1) {
                int v = gpiod_line_get_value(line);
                if (v < 0) return -1;
                if (v == 0) break;
                clock_gettime(CLOCK_MONOTONIC, &t_high_now);
                long us = (t_high_now.tv_sec - t_high_start.tv_sec) * 1000000L + (t_high_now.tv_nsec - t_high_start.tv_nsec) / 1000L;
                if (us > 1000) return -1;
            }
            long high_us = (t_high_now.tv_sec - t_high_start.tv_sec) * 1000000L + (t_high_now.tv_nsec - t_high_start.tv_nsec) / 1000L;
            if (high_us > 50) {
                data[i] |= (1 << j);
            }
        }
    }

    /* Checksum */
    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -1;

    *hum = (float)(((uint16_t)data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((uint16_t)(data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting DHT22 readings on GPIO %d and %d...\n", DHT22_PIN_1, DHT22_PIN_2);

    for (int cycle = 0; cycle < MAX_CYCLES && running; cycle++) {
        float t1, h1, t2, h2;
        int r1 = read_dht22(line1, &t1, &h1);
        int r2 = read_dht22(line2, &t2, &h2);

        if (r1 == 0) {
            printf("Cycle %d: GPIO %d -> Temp: %.1f C, Humidity: %.1f %%\n", cycle + 1, DHT22_PIN_1, t1, h1);
        } else {
            fprintf(stderr, "Cycle %d: Error reading from GPIO %d\n", cycle + 1, DHT22_PIN_1);
        }

        if (r2 == 0) {
            printf("Cycle %d: GPIO %d -> Temp: %.1f C, Humidity: %.1f %%\n", cycle + 1, DHT22_PIN_2, t2, h2);
        } else {
            fprintf(stderr, "Cycle %d: Error reading from GPIO %d\n", cycle + 1, DHT22_PIN_2);
        }

        if (cycle < MAX_CYCLES - 1 && running) {
            sleep(CYCLE_INTERVAL_SEC);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

