#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (int i = 0; i < 3; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int duty = (i + 1) * 100; /* 100, 200, 300 */
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d -> PWM %d\n", pins[i], duty);
        }
        fflush(stdout);
        gpioDelay(1000000); /* 1 second in microseconds */
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

