#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_16 16
#define GPIO_20 20
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line16 = NULL;
    struct gpiod_line *line20 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line16 = gpiod_chip_get_line(chip, GPIO_16);
    if (!line16) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_16, strerror(errno));
        goto cleanup;
    }
    line20 = gpiod_chip_get_line(chip, GPIO_20);
    if (!line20) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_20, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value low */
    if (gpiod_line_request_output(line16, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_16, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line20, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_20, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d set to LOW\n", GPIO_16, GPIO_20);
    fflush(stdout);

    while (running) {
        if (gpiod_line_set_value(line16, 1) < 0 || gpiod_line_set_value(line20, 1) < 0) {
            fprintf(stderr, "Error: failed to set HIGH: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set to HIGH\n", GPIO_16, GPIO_20);
        fflush(stdout);

        usleep(DELAY_MS * 1000);

        if (!running) break;

        if (gpiod_line_set_value(line16, 0) < 0 || gpiod_line_set_value(line20, 0) < 0) {
            fprintf(stderr, "Error: failed to set LOW: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set to LOW\n", GPIO_16, GPIO_20);
        fflush(stdout);

        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines (safe to call even if not requested) */
    if (line16) gpiod_line_release(line16);
    if (line20) gpiod_line_release(line20);
    if (chip)   gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 4000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: Fault detected (bit D16 set)\n");
        goto cleanup;
    }

    int16_t thermocouple_temp_raw = (int16_t)(raw >> 18);
    float thermocouple_temp = thermocouple_temp_raw * 0.25f;

    int16_t internal_temp_raw = (int16_t)((raw >> 4) & 0x07FF);
    if (internal_temp_raw & 0x0400) {
        internal_temp_raw |= 0xF800;
    }
    float internal_temp = internal_temp_raw * 0.0625f;

    printf("Thermocouple Temperature: %.2f °C\n", thermocouple_temp);
    printf("Internal Temperature: %.2f °C\n", internal_temp);

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_17 17
#define PIN_18 18

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18;
    int ret;

    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, PIN_17);
    line18 = gpiod_chip_get_line(chip, PIN_18);
    if (!line17 || !line18) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 18)");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 17)");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 18)");
            break;
        }
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");
        fflush(stdout);

        usleep(100000);

        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 17)");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 18)");
            break;
        }
        printf("GPIO 17: LOW, GPIO 18: HIGH\n");
        fflush(stdout);

        usleep(100000);
    }

    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(50000);

    printf("HC-SR04 Ultrasonic Sensor Test (libgpiod)\n");

    while (running) {
        /* Send 10us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Wait for echo rising edge (timeout ~30ms) */
        long long t_start = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 1) break;
            if (now_ns() - t_start > 30000000LL) {
                fprintf(stderr, "Timeout waiting for echo rising edge.\n");
                goto cleanup;
            }
            usleep(100);
        }
        if (!running) break;

        /* Measure echo pulse width (timeout ~30ms) */
        long long rise = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo pin: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 0) break;
            if (now_ns() - rise > 30000000LL) {
                fprintf(stderr, "Timeout waiting for echo falling edge.\n");
                goto cleanup;
            }
            usleep(100);
        }
        if (!running) break;

        long long pulse_us = (now_ns() - rise) / 1000LL;
        float distance = (pulse_us / 1000000.0f) * 34300.0f / 2.0f;

        printf("Distance: %.2f cm\n", distance);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

