#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define BMP280_I2C_ADDR 0x03

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_ID 0xD0
#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t id = 0;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read BMP280 chip ID\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3 && running; i++) {
        uint8_t t[3], p[3];
        if (i2c_read_reg(fd, BMP280_REG_PRESSURE_MSB, p, 3) < 0) {
            fprintf(stderr, "Error: Failed to read pressure data\n");
            break;
        }
        if (i2c_read_reg(fd, BMP280_REG_TEMP_MSB, t, 3) < 0) {
            fprintf(stderr, "Error: Failed to read temperature data\n");
            break;
        }

        int32_t raw_p = ((int32_t)p[0] << 12) | ((int32_t)p[1] << 4) | ((int32_t)p[2] >> 4);
        int32_t raw_t = ((int32_t)t[0] << 12) | ((int32_t)t[1] << 4) | ((int32_t)t[2] >> 4);

        printf("Reading %d: Pressure = %d, Temperature = %d\n", i + 1, raw_p, raw_t);
        fflush(stdout);

        if (i < 2) sleep(1);
    }

    close(fd);
    return EXIT_SUCCESS;
}

