#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_ALS_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val & 0xFF), (uint8_t)((val >> 8) & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (select reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Power on, ALS enabled, IT=50ms, HD=1 */
    if (i2c_write_reg8(fd, VEML7700_REG_ALS_CONF, 0x0001) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    usleep(50000);

    while (running) {
        uint16_t als;
        if (i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, &als) < 0) {
            break;
        }
        printf("VEML7700 ALS: %u\n", als);
        fflush(stdout);
        usleep(500000);
    }

    /* Power down */
    i2c_write_reg8(fd, VEML7700_REG_ALS_CONF, 0x0000);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int configure_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) == -1) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS + 50) / 100; /* deciseconds */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    } else if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_fd != -1) {
        close(g_fd);
        g_fd = -1;
    }
}

int main(void) {
    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_fd = configure_serial(SERIAL_PORT, BAUD_RATE);
    if (g_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    int consecutive_errors = 0;

    while (g_running) {
        int bytes_read = read_data(g_fd, buffer, sizeof(buffer));

        if (bytes_read > 0) {
            consecutive_errors = 0;
            printf("Received: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read == -1) {
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive read errors, exiting.\n");
                break;
            }
        }

        usleep(100000); /* 0.1 seconds */
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long diff_us(const struct timespec *a, const struct timespec *b) {
    return (long)(b->tv_sec - a->tv_sec) * 1000000L + (b->tv_nsec - a->tv_nsec) / 1000L;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        struct timespec t_start, t_pulse, t_end;
        long elapsed_us;

        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger set low failed: %s\n", strerror(errno));
            break;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger set high failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger set low failed: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge (timeout) */
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        while (gpiod_line_get_value(echo) == 0) {
            if (!running) goto done;
            if (diff_us(&t_start, &(struct timespec){.tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000}) > 0) {
                fprintf(stderr, "Timeout waiting for echo rising edge.\n");
                goto done;
            }
            usleep(10);
        }
        clock_gettime(CLOCK_MONOTONIC, &t_pulse);

        /* Wait for echo falling edge (timeout) */
        while (gpiod_line_get_value(echo) == 1) {
            if (!running) goto done;
            if (diff_us(&t_pulse, &(struct timespec){.tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000}) > 0) {
                fprintf(stderr, "Timeout waiting for echo falling edge.\n");
                goto done;
            }
            usleep(10);
        }
        clock_gettime(CLOCK_MONOTONIC, &t_end);

        elapsed_us = diff_us(&t_pulse, &t_end);

        /* Validity check: 2 cm .. 400 cm -> ~20 us .. 23 ms */
        if (elapsed_us >= 20 && elapsed_us <= 23000) {
            float distance = (float)elapsed_us / 58.0f;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid reading: %ld us\n", elapsed_us);
        }

        usleep(500000);
    }

done:
    ret = EXIT_SUCCESS;
cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

