#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL       0x2D
#define DATA_FORMAT     0x31
#define DATAX0          0x32

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int16_t x, y, z;
    uint8_t buf[6];

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Standby -> Measure */
    uint8_t pwr = 0x08;
    if (write(fd, &pwr, 1) != 1) {
        perror("write POWER_CTL");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Full resolution, +/-2g range */
    uint8_t fmt = 0x08;
    if (write(fd, &fmt, 1) != 1) {
        perror("write DATA_FORMAT");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Read 6 bytes starting at DATAX0 */
    uint8_t reg = DATAX0;
    if (write(fd, &reg, 1) != 1) {
        perror("write DATAX0");
        close(fd);
        return EXIT_FAILURE;
    }

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "read failed: got %zd bytes\n", n);
        close(fd);
        return EXIT_FAILURE;
    }

    x = (int16_t)((buf[1] << 8) | buf[0]);
    y = (int16_t)((buf[3] << 8) | buf[2]);
    z = (int16_t)((buf[5] << 8) | buf[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(fd);
    return EXIT_SUCCESS;
}

