#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int value = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, value) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for value %d\n", value);
            break;
        }
        printf("PWM value: %d\n", value);
        fflush(stdout);

        value++;
        if (value > PWM_RANGE) {
            value = 0;
        }

        time_sleep(0.1);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CYCLES 5
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line17 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on most Raspberry Pi models) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, 4);
    line17 = gpiod_chip_get_line(chip, 17);
    if (!line4 || !line17) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line4, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting %d cycles. Press Ctrl+C to stop early.\n", NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line4, val) < 0 ||
            gpiod_line_set_value(line17, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("Cycle %d: GPIO 4 and GPIO 17 set to %s\n",
               i + 1, val ? "HIGH" : "LOW");

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually, then close chip */
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Program finished.\n");
    else
        fprintf(stderr, "Program terminated with error.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_21 21
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line21 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line21 = gpiod_chip_get_line(chip, GPIO_21);
    if (!line17 || !line21) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio-toggle", 0) < 0 ||
        gpiod_line_request_output(line21, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0 || gpiod_line_set_value(line21, 1) < 0) {
            fprintf(stderr, "Failed to set high: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO 17 HIGH, GPIO 21 HIGH\n");
        fflush(stdout);

        usleep(DELAY_MS * 1000);

        if (!running) break;

        if (gpiod_line_set_value(line17, 0) < 0 || gpiod_line_set_value(line21, 0) < 0) {
            fprintf(stderr, "Failed to set low: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO 17 LOW, GPIO 21 LOW\n");
        fflush(stdout);

        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line21) gpiod_line_release(line21);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set both pins as outputs */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: drive each pin high, wait, low, wait, until interrupted */
    while (running) {
        if (gpioWrite(PWM_PIN_1, 1) != 0 || gpioWrite(PWM_PIN_2, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH\n");
            break;
        }
        printf("GPIO %d and GPIO %d HIGH\n", PWM_PIN_1, PWM_PIN_2);
        fflush(stdout);

        time_sleep(0.01);

        if (!running) break;

        if (gpioWrite(PWM_PIN_1, 0) != 0 || gpioWrite(PWM_PIN_2, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW\n");
            break;
        }
        printf("GPIO %d and GPIO %d LOW\n", PWM_PIN_1, PWM_PIN_2);
        fflush(stdout);

        time_sleep(0.01);
    }

    /* Clean up: ensure pins are low and terminate pigpio */
    gpioWrite(PWM_PIN_1, 0);
    gpioWrite(PWM_PIN_2, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

