#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define NUM_SENSORS  3

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig[NUM_SENSORS];
    struct gpiod_line *echo[NUM_SENSORS];
    int pins[NUM_SENSORS][2] = { {17, 18}, {17, 27}, {27, 18} };
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        trig[i] = NULL;
        echo[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        trig[i] = gpiod_chip_get_line(chip, pins[i][0]);
        if (!trig[i]) {
            fprintf(stderr, "Failed to get trigger line %d: %s\n", pins[i][0], strerror(errno));
            goto cleanup;
        }
        echo[i] = gpiod_chip_get_line(chip, pins[i][1]);
        if (!echo[i]) {
            fprintf(stderr, "Failed to get echo line %d: %s\n", pins[i][1], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_output(trig[i], "hcsr04-trig", 0) < 0) {
            fprintf(stderr, "Failed to request trigger line %d as output: %s\n", pins[i][0], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(echo[i], "hcsr04-echo") < 0) {
            fprintf(stderr, "Failed to request echo line %d as input: %s\n", pins[i][1], strerror(errno));
            goto cleanup;
        }
    }

    printf("HC-SR04 Ultrasonic Sensor Interface (libgpiod)\n");
    printf("Trigger pins: ");
    for (int i = 0; i < NUM_SENSORS; i++) printf("%d ", pins[i][0]);
    printf("\nEcho pins:    ");
    for (int i = 0; i < NUM_SENSORS; i++) printf("%d ", pins[i][1]);
    printf("\n");

    for (int s = 0; s < NUM_SENSORS && running; s++) {
        if (gpiod_line_set_value(trig[s], 0) < 0) {
            fprintf(stderr, "Error setting trigger low on sensor %d: %s\n", s, strerror(errno));
            goto cleanup;
        }
        usleep(2);

        if (gpiod_line_set_value(trig[s], 1) < 0) {
            fprintf(stderr, "Error setting trigger high on sensor %d: %s\n", s, strerror(errno));
            goto cleanup;
        }
        usleep(10);

        if (gpiod_line_set_value(trig[s], 0) < 0) {
            fprintf(stderr, "Error setting trigger low on sensor %d: %s\n", s, strerror(errno));
            goto cleanup;
        }

        long long start_tick = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo[s]);
            if (val < 0) {
                fprintf(stderr, "Error reading echo pin on sensor %d: %s\n", s, strerror(errno));
                goto cleanup;
            }
            if (val == 1) break;
            if (now_ns() - start_tick > 100000000LL) {
                fprintf(stderr, "Timeout waiting for echo high on sensor %d\n", s);
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        long long pulse_start = now_ns();
        while (running) {
            int val = gpiod_line_get_value(echo[s]);
            if (val < 0) {
                fprintf(stderr, "Error reading echo pin on sensor %d: %s\n", s, strerror(errno));
                goto cleanup;
            }
            if (val == 0) break;
            if (now_ns() - pulse_start > 100000000LL) {
                fprintf(stderr, "Timeout waiting for echo low on sensor %d\n", s);
                goto cleanup;
            }
            usleep(10);
        }
        if (!running) break;

        long long pulse_duration = now_ns() - pulse_start;
        float distance = (pulse_duration / 1000000000.0f) * 34300.0f / 2.0f;

        printf("Sensor %d: Distance = %.2f cm\n", s, distance);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (trig[i]) gpiod_line_release(trig[i]);
        if (echo[i]) gpiod_line_release(echo[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int states[3] = {50, 75, 100};

    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set mode for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], states[i]) != 0) {
            fprintf(stderr, "Failed to set PWM for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Pin %d: PWM duty cycle set to %d%%\n", pins[i], states[i]);
    }

    while (running) {
        gpioDelay(100000);
    }

    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

