        struct timespec t_start, t_pulse, t_end;
        long elapsed_us;

        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_start);
        elapsed_us = 0;
        while (gpiod_line_get_value(echo) == 0 && running) {
            clock_gettime(CLOCK_MONOTONIC, &t_pulse);
            if (diff_us(&t_start, &t_pulse) > TIMEOUT_US) {
                printf("Timeout waiting for echo start.\n");
                goto next_iter;
            }
        }
        if (!running) break;

        clock_gettime(CLOCK_MONOTONIC, &t_pulse);
        while (gpiod_line_get_value(echo) == 1 && running) {
            clock_gettime(CLOCK_MONOTONIC, &t_end);
            if (diff_us(&t_pulse, &t_end) > TIMEOUT_US) {
                printf("Timeout waiting for echo end.\n");
                goto next_iter;
            }
        }
        if (!running) break;

        elapsed_us = diff_us(&t_pulse, &t_end);
        float distance = (elapsed_us / 2.0f) * 0.0343f;

        if (distance < 2.0f || distance > 400.0f) {
            printf("Distance out of range: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

    next_iter:
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define PWM_PIN 16

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Set PWM range to 255 (8-bit resolution) */
    if (gpioSetPWMrange(PWM_PIN, 255) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1 kHz */
    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Drive PWM at 50% duty cycle */
    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d: 50%% duty cycle @ 1 kHz\n", PWM_PIN);
    fflush(stdout);

    /* Wait until interrupted */
    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped. Resources released.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_CDATAH  0x15
#define TCS34725_RDATAL  0x16
#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Error: TCS34725 not responding at 0x%02X\n", TCS34725_ADDRESS);
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Warning: unexpected ID 0x%02X (expected 0x44 or 0x10)\n", id);
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) {
        perror("enable power");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (i2c_read_reg16(fd, TCS34725_CDATAL, &clear) < 0 ||
            i2c_read_reg16(fd, TCS34725_RDATAL, &red)   < 0 ||
            i2c_read_reg16(fd, TCS34725_GDATAL, &green) < 0 ||
            i2c_read_reg16(fd, TCS34725_BDATAL, &blue)  < 0) {
            perror("read color data");
            break;
        }

        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        fflush(stdout);

        usleep(500000);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_18 18
#define GPIO_23 23

static volatile sig_atomic_t running = 1;

static void sighandler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error: cannot get GPIO %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        fprintf(stderr, "Error: cannot get GPIO %d: %s\n", GPIO_23, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line23, "gpio-toggle", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO %d as output: %s\n", GPIO_23, strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d high: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line23, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d low: %s\n", GPIO_23, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d HIGH, GPIO %d LOW\n", GPIO_18, GPIO_23);
        fflush(stdout);

        usleep(10000); /* 10 ms */

        if (!running) break;

        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d low: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line23, 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d high: %s\n", GPIO_23, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d LOW, GPIO %d HIGH\n", GPIO_18, GPIO_23);
        fflush(stdout);

        usleep(10000); /* 10 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
