    for (i = 0; i < NUM_PINS && running; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set line %u high\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO pin %u set HIGH\n", pins[i]);
    }

    for (i = 0; i < NUM_PINS && running; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set line %u low\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO pin %u set LOW\n", pins[i]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
