    printf("GPIO %d initialized as output (LOW). Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d state: %s\n", GPIO_LINE_OFFSET, value ? "HIGH" : "LOW");
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

