#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define CHIP_NAME "gpiochip0"
#define PIN_1 22
#define PIN_2 24

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    signal(SIGINT, int_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, PIN_1);
    line2 = gpiod_chip_get_line(chip, PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line1");
            break;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line2");
            break;
        }
        printf("GPIO %d HIGH, GPIO %d LOW\n", PIN_1, PIN_2);
        usleep(10000);

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line1");
            break;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line2");
            break;
        }
        printf("GPIO %d LOW, GPIO %d HIGH\n", PIN_1, PIN_2);
        usleep(10000);
    }

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

