        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio18-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("GPIO %d: %s\n", GPIO_LINE, val ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

