#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define VCC_PIN     24

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 50000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long deadline_us) {
    while (running) {
        if (gpiod_line_get_value(line) == level)
            return 0;
        if (now_us() >= deadline_us)
            return -1;
        usleep(10);
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *vcc = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc  = gpiod_chip_get_line(chip, VCC_PIN);
    if (!trig || !echo || !vcc) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04-echo") < 0 ||
        gpiod_line_request_output(vcc, "hcsr04-vcc") < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_set_value(vcc, 1) < 0) {
        fprintf(stderr, "Failed to power sensor: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(100000);

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(2000);

    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }

    long long t_start = now_us();
    if (wait_for_level(echo, 1, t_start + TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        goto cleanup;
    }
    long long t_rise = now_us();

    if (wait_for_level(echo, 0, t_rise + TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        goto cleanup;
    }
    long long t_fall = now_us();

    long long pulse_us = t_fall - t_rise;
    double distance_cm = (pulse_us / 1000000.0) * SPEED_OF_SOUND_CM_PER_S / 2.0;

    if (distance_cm > MAX_DISTANCE_CM)
        distance_cm = MAX_DISTANCE_CM;

    printf("Distance: %.2f cm\n", distance_cm);
    rc = EXIT_SUCCESS;

cleanup:
    if (vcc) gpiod_line_set_value(vcc, 0);
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc)  gpiod_line_release(vcc);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int read_input(void) {
    char input[32];
    printf("Enter value (0 or 1): ");
    fflush(stdout);

    if (!fgets(input, sizeof(input), stdin)) {
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1;
    }

    if (input[strcspn(input, "\n")] != '\0') {
        input[strcspn(input, "\n")] = '\0';
    }

    if (strcmp(input, "0") == 0) return 0;
    if (strcmp(input, "1") == 0) return 1;

    fprintf(stderr, "Invalid input. Please enter 0 or 1.\n");
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line 18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    while (running) {
        int value = read_input();
        if (value < 0) {
            if (!running) break;
            continue;
        }

        if (gpiod_line_set_value(line, value) < 0) {
            perror("Failed to set GPIO value");
            goto cleanup;
        }

        printf("GPIO 18 set to: %d\n", value);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(PWM_PIN, PI_OUTPUT);

    /* Set PWM range and frequency */
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    int increment = 10;

    while (running) {
        if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", PWM_PIN);
            break;
        }

        printf("GPIO %d: PWM duty cycle = %d/%d\n", PWM_PIN, duty_cycle, PWM_RANGE);
        fflush(stdout);

        duty_cycle += increment;
        if (duty_cycle >= PWM_RANGE) {
            duty_cycle = PWM_RANGE;
            increment = -10;
        } else if (duty_cycle <= 0) {
            duty_cycle = 0;
            increment = 10;
        }

        time_sleep(0.2);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

